import sys

REGS = ('a', 'b', 'c', 'd')

def parse_operand(tok, regs):
    if tok in REGS:
        return regs[tok]
    return int(tok)

def main(path):
    instrs = []
    with open(path) as f:
        for raw in f:
            line = raw.split(';', 1)[0].strip()
            if not line:
                continue
            parts = line.split()
            instrs.append(parts)
    regs = {r: 0 for r in REGS}
    outputs = []
    pc = 0
    count = 0
    n = len(instrs)
    steps = 0
    while 0 <= pc < n:
        parts = instrs[pc]
        op = parts[0]
        count += 1
        steps += 1
        if steps > 10_000_000:
            print("STEP LIMIT", file=sys.stderr)
            break
        next_pc = pc + 1
        if op == 'set':
            r = parts[1]
            x = parse_operand(parts[2], regs)
            regs[r] = x % 65536
        elif op == 'add':
            r = parts[1]
            x = parse_operand(parts[2], regs)
            regs[r] = (regs[r] + x) % 65536
        elif op == 'mul':
            r = parts[1]
            x = parse_operand(parts[2], regs)
            regs[r] = (regs[r] * x) % 65536
        elif op == 'mod':
            r = parts[1]
            x = parse_operand(parts[2], regs)
            if x > 0:
                regs[r] = regs[r] % x
        elif op == 'dec':
            r = parts[1]
            if regs[r] > 0:
                regs[r] -= 1
        elif op == 'jnz':
            x = parse_operand(parts[1], regs)
            k = parse_operand(parts[2], regs)
            if x != 0:
                next_pc = pc + k
        elif op == 'skp':
            x = parse_operand(parts[1], regs)
            y = parse_operand(parts[2], regs)
            if x < y:
                next_pc = pc + 2
        elif op == 'out':
            x = parse_operand(parts[1], regs)
            outputs.append(x)
        else:
            raise ValueError(op)
        pc = next_pc
    print("outputs:", outputs)
    print("sum:", sum(outputs))
    print("count:", count)
    print("regs:", regs)

main(sys.argv[1])

