const fs = require('fs');
const lines = fs.readFileSync('prog.pw9','utf8').split('\n');
const prog = [];
for (let l of lines) {
  l = l.split(';')[0].trim();
  if (l) prog.push(l.split(/\s+/));
}
const R = {a:0,b:0,c:0,d:0};
const val = t => (t in R) ? R[t] : parseInt(t,10);
let pc=0, count=0, outs=[];
while (pc>=0 && pc<prog.length) {
  const ins=prog[pc]; count++;
  let np=pc+1;
  const op=ins[0];
  if (op==='set') R[ins[1]] = ((val(ins[2])%65536)+65536)%65536;
  else if (op==='add') R[ins[1]] = (((R[ins[1]]+val(ins[2]))%65536)+65536)%65536;
  else if (op==='mul') R[ins[1]] = (((R[ins[1]]*val(ins[2]))%65536)+65536)%65536;
  else if (op==='mod') { const x=val(ins[2]); if (x>0) R[ins[1]]=R[ins[1]]%x; }
  else if (op==='dec') { if (R[ins[1]]>0) R[ins[1]]--; }
  else if (op==='jnz') { if (val(ins[1])!==0) np=pc+val(ins[2]); }
  else if (op==='skp') { if (val(ins[1])<val(ins[2])) np=pc+2; }
  else if (op==='out') outs.push(val(ins[1]));
  else throw new Error(op);
  pc=np;
}
console.log(JSON.stringify({n:outs.length, sum:outs.reduce((x,y)=>x+y,0), count, last:outs.slice(-6), regs:R}));

