import importlib.util, sys, io
# quick instrumented run using same parser
REGS=('a','b','c','d')
instrs=[]
for raw in open('prog.pw9'):
    line=raw.split(';',1)[0].strip()
    if line: instrs.append(line.split())
regs={r:0 for r in REGS}
def v(t): return regs[t] if t in REGS else int(t)
pc=0;count=0;outs=[];iters=0;skips=0;ddecs=0
while 0<=pc<len(instrs):
    p=instrs[pc];op=p[0];count+=1;np=pc+1
    if op=='set': regs[p[1]]=v(p[2])%65536
    elif op=='add': regs[p[1]]=(regs[p[1]]+v(p[2]))%65536
    elif op=='mul': regs[p[1]]=(regs[p[1]]*v(p[2]))%65536
    elif op=='mod':
        x=v(p[2])
        if x>0: regs[p[1]]%=x
    elif op=='dec':
        if regs[p[1]]>0:
            regs[p[1]]-=1
            if p[1]=='d': ddecs+=1
    elif op=='jnz':
        if v(p[1])!=0: np=pc+v(p[2])
    elif op=='skp':
        if v(p[1])<v(p[2]):
            np=pc+2; skips+=1
    elif op=='out': outs.append(v(p[1]))
    if pc==13: iters+=1
    pc=np
print('outputs',len(outs),'iters',iters,'skips(index9)',skips,'ddecs',ddecs,'count',count,'sum',sum(outs))
